sql:
SELECT count(DISTINCT city)
FROM zip_code
WHERE county = 'Orange County' AND state = 'Virginia';

SELECT player_name
FROM Player
WHERE birthday LIKE '1970-10%';

SELECT SUM(T1.Consumption)
FROM yearmonth AS T1
WHERE T1.CustomerID = 6 AND T1.Date BETWEEN '201308' AND '201311';

SELECT MAX(Consumption)
FROM yearmonth
WHERE Date LIKE '2012%';

SELECT
  AVG(CASE WHEN T1.isStorySpotlight = 1 AND T1.isTextless = 0 THEN 100.0 ELSE 0 END)
FROM cards AS T1;
